<?php defined('ALTUMCODE') || die();$program=fcc_seminar_program($d); ?>
<?php if($d['organizer']): ?><p class="fs-organizer"><?= $h(fcc_seminar_t('Organizator')) ?>: <?= $h($d['organizer']) ?></p><?php endif ?>
<?php if($program): ?><section class="fs-program" aria-labelledby="event-program"><span class="fs-kicker"><?= $h(fcc_seminar_t('IDEJE, LJUDI I NOVI KORACI')) ?></span><h2 id="event-program"><?= $h(fcc_seminar_t('Program i predavači')) ?></h2><div class="fs-program-grid"><?php foreach($program as $item): ?><article><span class="fs-program-dot" aria-hidden="true"></span><div><h3><?= $h($item['name']) ?></h3><small><?= $h(fcc_seminar_t($item['role'])) ?></small><p><?= $h(fcc_seminar_t($item['topic'])) ?></p></div></article><?php endforeach ?></div></section><?php endif ?>
<?php if($d['gallery']): ?><details class="fs-gallery"><summary><?= $h(fcc_seminar_t('Pogledaj najave i fotografije')) ?> <span><?= count($d['gallery']) ?></span></summary><p><?= $h(fcc_seminar_t('Dodirni fotografiju za cijeli prikaz. Aktualne teme navedene su u programu iznad.')) ?></p><div class="fs-gallery-grid"><?php foreach($d['gallery'] as $i=>$asset): ?><a href="<?= $h(fcc_event_asset_url($asset)) ?>" target="_blank" rel="noopener"><img src="<?= $h(fcc_event_asset_url($asset)) ?>" loading="lazy" alt="<?= $h(fcc_seminar_t('Najava događaja')) ?> <?= $i+1 ?>"></a><?php endforeach ?></div></details><?php endif ?>
